using Phantom.Diagnostics;using Phantom.Logging;using Phantom.Mapping;using Phantom.RobotLocalization;using Phantom.Tracking;using Phantom.UI;using Phantom.Visualization;using UnityEngine;
namespace Phantom
{
    // Stage-2 runtime is intentionally observation-only. No RobotTransport is
    // constructed until discovery, commissioning hashes and references exist.
    public sealed class PhantomRuntime:MonoBehaviour
    {
        MetaQuestTrackingSource _tracking;PhantomWristHud _hud;QuestJsonlLogger _logger;readonly PhantomStateMachine _state=new PhantomStateMachine();EnableHysteresis _enable;PhantomState _previous=PhantomState.Boot;double _nextHud;IRobotMarkerTracker _enabledQrTracker;
        void Awake(){_tracking=GetComponent<MetaQuestTrackingSource>()??gameObject.AddComponent<MetaQuestTrackingSource>();_hud=GetComponent<PhantomWristHud>()??gameObject.AddComponent<PhantomWristHud>();_logger=new QuestJsonlLogger();_enable=new EnableHysteresis();_logger.Log("runtime","stage2_observation_start",_state.State.ToString(),"","{\"motor_authority\":false}");}
        void Update(){if(!_tracking.TryGetFrame(out var frame))frame.AppFocused=Application.isFocused;var held=_enable.Update(frame.LeftController.GripAnalog,frame.LeftController.Valid);var markers=RobotMarkerTrackerRegistry.Current;if(markers!=null&&!ReferenceEquals(markers,_enabledQrTracker)){_enabledQrTracker?.SetQrTrackingEnabled(false);markers.SetQrTrackingEnabled(true);_enabledQrTracker=markers;}var qrAvailable=markers!=null&&markers.IsAvailable;var predicates=new SafetyPredicates{AppFocused=frame.AppFocused,XrReady=frame.MultimodalConfigured&&_tracking.BodyProviderAvailable,WristValid=frame.RightHand.Wrist.Valid,ShoulderValid=frame.RightShoulder.Valid,LeftControllerValid=frame.LeftController.Valid,UserCalibrationValid=false,NetworkDiscovered=false,Connected=false,RobotReferenceValid=false,EnableHeld=held};var state=_state.Update(predicates);if(state!=_previous){_logger.Log("runtime","state_transition",state.ToString(),"","{\"from\":\""+_previous+"\"}");_previous=state;}if(Time.realtimeSinceStartupAsDouble<_nextHud)return;_nextHud=Time.realtimeSinceStartupAsDouble+.1;_hud.SetTracking(frame);_hud.Content=$"PHANTOM — {Russian(state)}\nДВИЖЕНИЕ ЗАПРЕЩЕНО (ЭТАП 2)\nXR {_tracking.MultimodalStatus}  ПЛЕЧО {(frame.RightShoulder.Valid?"ВИДНО":"НЕТ")}  WRIST {(frame.RightHand.Wrist.Valid?"ВИДНО":"НЕТ")}\nЛЕВЫЙ TOUCH {(frame.LeftController.Valid?"ГОТОВ":"НЕТ")}  QR {(qrAvailable?markers.StatusReason:"ОЖИДАНИЕ CAPABILITY")}\n{StartupWizardModel.Instruction(state)}";}
        static string Russian(PhantomState s){switch(s){case PhantomState.Boot:return "ЗАПУСК";case PhantomState.UserCalibration:return "КАЛИБРОВКА ПОЛЬЗОВАТЕЛЯ";case PhantomState.Discovery:return "ПОИСК EV3";case PhantomState.ConnectedUnreferenced:return "НУЖНА QR-ПРИВЯЗКА";case PhantomState.Ready:return "ГОТОВО";case PhantomState.Hold:return "УДЕРЖАНИЕ";case PhantomState.Tracking:return "УПРАВЛЕНИЕ";case PhantomState.SafeHold:return "БЕЗОПАСНАЯ ОСТАНОВКА";case PhantomState.Stopped:return "ЛОКАЛЬНАЯ ОСТАНОВКА";default:return "ОШИБКА";}}
        void OnApplicationFocus(bool focused){if(!focused)_state.OnReferenceSpaceChange();}void OnApplicationPause(bool paused){if(paused)_state.OnReferenceSpaceChange();}void OnDestroy(){_enabledQrTracker?.SetQrTrackingEnabled(false);_logger?.Dispose();}
    }
    public static class PhantomBootstrap{[RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.AfterSceneLoad)]static void Install(){if(Object.FindFirstObjectByType<PhantomRuntime>()!=null)return;var go=new GameObject("PhantomRuntime");Object.DontDestroyOnLoad(go);go.AddComponent<PhantomRuntime>();go.AddComponent<QuestDeviceAuto>();
#if DEVELOPMENT_BUILD
        go.AddComponent<Phantom.Experiments.QuestValidationRunner>();
#endif
    }}
}
